import {isMaster,canManageToken,validSession} from './access.js';
import {initThemePicker} from './themes.js';
import {roll,initiativeOrder} from './engine.js';
const $=s=>document.querySelector(s), key='tavern-campaign-v1';
const initial={name:'Затерянные в тумане',round:1,turn:0,notes:'',logs:[],grid:true,fog:false,paths:[],tokens:[{id:'a',name:'Элиан',kind:'hero',hp:28,max:28,ac:15,mod:3,x:42,y:67,init:null},{id:'b',name:'Торин',kind:'hero',hp:38,max:38,ac:18,mod:1,x:51,y:73,init:null},{id:'c',name:'Лира',kind:'hero',hp:22,max:22,ac:13,mod:2,x:59,y:65,init:null},{id:'d',name:'Гоблин 1',kind:'enemy',hp:7,max:7,ac:15,mod:2,x:44,y:40,init:null},{id:'e',name:'Гоблин 2',kind:'enemy',hp:7,max:7,ac:15,mod:2,x:58,y:34,init:null}]};
let state;try{state=JSON.parse(localStorage.getItem(key))||structuredClone(initial)}catch{state=structuredClone(initial)}let mode='move',filter='all',drag=null,activePath=null;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=null;
const master=()=>isMaster(session);
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{notify('Не удалось сохранить: хранилище браузера заполнено. Экспортируйте кампанию.')}}
function addLog(label,result,detail=''){state.logs.unshift({label,result,detail,time:new Date().toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'})});state.logs=state.logs.slice(0,60);save();renderLog()}
function renderLog(){$('#log').innerHTML=state.logs.length?state.logs.map(l=>`<div class="logitem"><time>${esc(l.time)}</time><span>${esc(l.label)} <small>${esc(l.detail)}</small></span><b>${esc(l.result)}</b></div>`).join(''):'<p style="font-size:11px">Приключение начинается с первого броска.</p>'}
function ordered(){return initiativeOrder(state.tokens)}
function render(){const order=ordered(),current=order[state.turn%Math.max(1,order.length)];$('#tokens').innerHTML=state.tokens.map(t=>`<button class="token ${t.kind} ${current?.id===t.id&&t.init!==null?'current':''}" style="left:${t.x}%;top:${t.y}%" data-id="${esc(t.id)}" aria-label="${esc(t.name)}, HP ${t.hp}">${t.kind==='enemy'?'♟':esc(t.name[0])}<small>${esc(t.name)}</small></button>`).join('');$('#initiativeList').innerHTML=order.map(t=>`<div class="fighter ${current?.id===t.id&&t.init!==null?'turn':''}"><span class="portrait ${t.kind}">${t.kind==='enemy'?'♟':esc(t.name[0])}</span><div class="fighterinfo"><strong>${esc(t.name)}</strong><small>♥ ${t.hp}/${t.max} &nbsp; ◇ КБ ${t.ac}</small></div><span class="score">${t.init??'—'}</span></div>`).join('');$('#round').textContent=`Раунд ${state.round}`;$('#nextTurn').disabled=!master()||!order.length||order.every(t=>t.init===null);$('.grid').style.display=state.grid?'':'none';$('#battlemap').classList.toggle('fog',state.fog);$('#gridTool').classList.toggle('selected',state.grid);$('#fogTool').classList.toggle('selected',state.fog);if(state.map){$('.terrain').style.display='none';$('#battlemap').style.backgroundImage=`url("${state.map}")`;$('#battlemap').style.backgroundSize='cover';$('#mapTitle').textContent='Пользовательская карта'}renderCharacters();renderLog();renderPaths();$('.crumb').innerHTML=`Кампании <span>/</span> ${esc(state.name)}`;$('#campaignName').innerHTML=`◈ &nbsp; ${esc(state.name)}<small>D&D 5e · 2014</small>`}
const titles={table:['Игровой стол','Соберите отряд. Разверните карту. Начните приключение.'],characters:['Ваш отряд','Герои, которым предстоит изменить эту историю.'],library:['Библиотека','Правила, существа и снаряжение для ваших приключений.'],notes:['Хроника кампании','Сохраните то, что однажды станет легендой.']};
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{const v=b.dataset.view;if(v==='notes'&&!master())return;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));for(const name of Object.keys(titles))$('#'+name+'View').classList.toggle('hidden',name!==v);$('#viewTitle').innerHTML=titles[v][0]+'<span>✦</span>';$('#viewSub').textContent=titles[v][1];$('#addToken').style.display=master()&&['table','characters'].includes(v)?'':'none'};
$('#addToken').onclick=()=>{if(master())$('#tokenDialog').showModal()};$('#cancelToken').onclick=()=>$('#tokenDialog').close();$('#tokenForm').onsubmit=e=>{e.preventDefault();if(!master())return;const f=new FormData(e.target),kind=f.get('kind');let n=1;while(state.tokens.some(t=>t.name===`Токен ${n}`))n++;const t={id:crypto.randomUUID(),name:String(f.get('name')).trim()||`Токен ${n}`,hp:Number(f.get('hp')),max:Number(f.get('hp')),ac:Number(f.get('ac')),mod:Number(f.get('mod')),kind,x:35+Math.random()*25,y:45+Math.random()*20,init:null};state.tokens.push(t);save();render();$('#tokenDialog').close();e.target.reset();notify(`${t.name} добавлен на карту`)};
$('#initiative').onclick=()=>{if(!master())return;for(const t of state.tokens)t.init=roll('1d20'+(t.mod>=0?'+':'')+t.mod).total;state.round=1;state.turn=0;addLog('Инициатива','⚔','Порядок участников обновлён');save();render()};$('#nextTurn').onclick=()=>{if(!master())return;state.turn++;if(state.turn>=state.tokens.length){state.turn=0;state.round++}save();render()};
$('#diceButtons').innerHTML=[4,6,8,10,12,20,100].map(n=>`<button data-die="${n}" title="Бросить d${n}">◇ d${n}</button>`).join('');function doRoll(formula){try{const r=roll(formula);addLog(formula,r.total,`[${r.rolls.join(', ')}]`)}catch(e){notify(e.message)}}$('#diceButtons').onclick=e=>{const b=e.target.closest('[data-die]');if(b)doRoll('1d'+b.dataset.die)};$('#rollFormula').onclick=()=>doRoll($('#diceFormula').value);$('#diceFormula').onkeydown=e=>{if(e.key==='Enter')doRoll(e.target.value)};$('#clearLog').onclick=()=>{if(!master())return;state.logs=[];save();renderLog()};
function coords(e){const r=$('#battlemap').getBoundingClientRect();return{x:Math.max(4,Math.min(96,(e.clientX-r.left)/r.width*100)),y:Math.max(8,Math.min(88,(e.clientY-r.top)/r.height*100))}}
$('#battlemap').onpointerdown=e=>{const b=e.target.closest('.token');if(e.target.closest('.maptools'))return;if(b&&mode==='move'){const t=state.tokens.find(t=>t.id===b.dataset.id);if(!canManageToken(session,t))return;drag=t;b.setPointerCapture(e.pointerId)}else if(mode==='draw'&&master()){activePath=[coords(e)];state.paths.push(activePath);$('#battlemap').setPointerCapture(e.pointerId)}};$('#battlemap').onpointermove=e=>{if(drag){Object.assign(drag,coords(e));const b=document.querySelector(`[data-id="${drag.id}"]`);b.style.left=drag.x+'%';b.style.top=drag.y+'%'}if(activePath){activePath.push(coords(e));renderPaths()}};function endPointer(){if(drag||activePath){drag=null;activePath=null;save()}}$('#battlemap').onpointerup=endPointer;$('#battlemap').onpointercancel=endPointer;function renderPaths(){$('#drawing').setAttribute('viewBox','0 0 100 100');$('#drawing').innerHTML=state.paths.map(p=>`<polyline points="${p.map(v=>v.x+','+v.y).join(' ')}" fill="none" stroke="#e0ce91" stroke-width=".4" stroke-linecap="round" stroke-linejoin="round"/>`).join('')}
$('#moveTool').onclick=()=>{mode='move';$('#moveTool').classList.add('selected');$('#drawTool').classList.remove('selected')};$('#drawTool').onclick=()=>{if(!master())return;mode='draw';$('#drawTool').classList.add('selected');$('#moveTool').classList.remove('selected')};$('#gridTool').onclick=()=>{state.grid=!state.grid;save();render()};$('#fogTool').onclick=()=>{if(!master())return;state.fog=!state.fog;save();render();notify(state.fog?'Карта затемнена на этом устройстве':'Карта открыта')};$('#clearDraw').onclick=()=>{if(!master())return;state.paths=[];save();renderPaths()};$('#resetMap').onclick=()=>{if(!master())return;state.tokens.forEach((t,i)=>{t.x=30+(i%5)*11;t.y=50+Math.floor(i/5)*13});save();render()};
$('#uploadBtn').onclick=()=>{if(master())$('#upload').click()};$('#upload').onchange=async e=>{const file=e.target.files[0];if(!master()||!file)return;if(!file.type.startsWith('image/'))return notify('Выберите изображение');if(file.size>4*1024*1024)return notify('Выберите карту размером до 4 МБ');const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{if(!master()){URL.revokeObjectURL(url);return}const c=document.createElement('canvas'),ratio=Math.min(1,1600/img.width);c.width=img.width*ratio;c.height=img.height*ratio;c.getContext('2d').drawImage(img,0,0,c.width,c.height);state.map=c.toDataURL('image/jpeg',.8);URL.revokeObjectURL(url);save();render();notify('Карта загружена')};img.onerror=()=>{URL.revokeObjectURL(url);notify('Не удалось прочитать изображение')};img.src=url};
function renderCharacters(){$('#charactersView').innerHTML=state.tokens.filter(t=>canManageToken(session,t)).map(t=>`<article class="charcard"><span class="portrait ${t.kind}">${t.kind==='enemy'?'♟':esc(t.name[0])}</span><h2>${esc(t.name)}</h2><div class="eyebrow">${t.kind==='hero'?'ПЕРСОНАЖ':'ПРОТИВНИК'}</div><div class="charstats"><span>КБ <b>${t.ac}</b></span><span>Инициатива <b>${t.mod>=0?'+':''}${t.mod}</b></span><span>Макс. HP <b>${t.max}</b></span></div><div class="hpcontrols" data-char="${esc(t.id)}"><button data-hp="-1" aria-label="Уменьшить HP">−</button><input type="number" min="0" max="${t.max}" value="${t.hp}" aria-label="Текущие HP"><button data-hp="1" aria-label="Увеличить HP">＋</button>${master()?`<button class="delete" data-delete="${esc(t.id)}" title="Удалить токен">Удалить</button>`:''}</div></article>`).join('')||'<p>Добавьте первого персонажа кнопкой выше.</p>'}
$('#charactersView').onclick=e=>{const d=e.target.closest('[data-delete]');if(d){if(!master())return;state.tokens=state.tokens.filter(t=>t.id!==d.dataset.delete);state.turn=0;save();render();return}const b=e.target.closest('[data-hp]');if(!b)return;const t=state.tokens.find(t=>t.id===b.closest('[data-char]').dataset.char);if(!canManageToken(session,t))return;t.hp=Math.max(0,Math.min(t.max,t.hp+Number(b.dataset.hp)));save();render()};$('#charactersView').onchange=e=>{if(e.target.type!=='number')return;const t=state.tokens.find(t=>t.id===e.target.closest('[data-char]').dataset.char);if(!canManageToken(session,t))return;t.hp=Math.max(0,Math.min(t.max,Number(e.target.value)||0));save();render()};
const library=[['rule','Проверки характеристик','Бросьте d20 и прибавьте модификатор характеристики. Если персонаж владеет соответствующим навыком, добавьте бонус мастерства. Результат сравнивается со сложностью.'],['rule','Преимущество и помеха','Бросьте два d20. При преимуществе используйте больший результат, при помехе — меньший. Преимущество и помеха взаимно отменяются.'],['rule','Ход в бою','В свой ход существо может переместиться на расстояние своей скорости и совершить действие. Бонусное действие доступно, если способность или правило его предоставляет.'],['rule','Инициатива','В начале боя участники совершают проверку Ловкости. Ходы идут от большего результата к меньшему; порядок сохраняется между раундами. Ничьи можно разрешить решением мастера.'],['monster','Гоблин','Маленький гуманоид · КБ 15 · HP 7 · скорость 30 футов. Ловкость 14 (+2). Стартовые данные для расстановки противников.'],['item','Факел','Горит 1 час, создавая яркий свет в радиусе 20 футов и тусклый свет ещё на 20 футов. Полезен в руинах и подземельях.']];function renderLibrary(){const q=$('#search').value.toLowerCase();$('#libraryCards').innerHTML=library.filter(([type,title,body])=>(filter==='all'||type===filter)&&(title+' '+body).toLowerCase().includes(q)).map(([type,title,body])=>`<article class="librarycard"><div class="eyebrow">${{rule:'ПРАВИЛА · 5e 2014',monster:'БЕСТИАРИЙ',item:'СНАРЯЖЕНИЕ'}[type]}</div><h2>${title}</h2><p>${body}</p></article>`).join('')||'<p>Ничего не найдено.</p>'}$('#search').oninput=renderLibrary;$('#filters').onclick=e=>{if(!e.target.dataset.filter)return;filter=e.target.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===e.target));renderLibrary()};$('#notes').value=state.notes;$('#notes').oninput=e=>{if(!master())return;state.notes=e.target.value;save()};$('#rename').onclick=()=>{if(!master())return;const n=prompt('Название кампании',state.name);if(n?.trim()){state.name=n.trim().slice(0,80);save();render()}};$('#campaignName').onclick=$('#rename').onclick;$('#export').onclick=()=>{if(!master())return;const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='rasputye-campaign.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Кампания экспортирована')};render();renderLibrary();

initThemePicker(notify);

const sessionKey='rasputye-session-v1';
let selectedRole=null;
const entry=$('#entryScreen'),workspace=$('#workspace');
function showEntry(){
  session=null;drag=null;activePath=null;selectedRole=null;entry.hidden=false;workspace.hidden=true;
  document.body.removeAttribute('data-role');
  document.querySelectorAll('[data-entry-role]').forEach(b=>b.setAttribute('aria-pressed','false'));
  $('#entryCharacterField').hidden=true;$('#entryContinue').disabled=true;$('#entryContinue').innerHTML='Выберите роль <span>→</span>';
  $('#entryRoleHint').innerHTML='Роль действует в этой кампании.<br>В другой истории вы сможете выбрать другую.';
  $('#entryCharacter').innerHTML=state.tokens.filter(t=>t.kind==='hero').map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');
}
function enter(next){
  if(!validSession(next,state.tokens))return;
  session=next;document.body.dataset.role=session.role;entry.hidden=true;workspace.hidden=false;mode='move';
  $('#moveTool').classList.add('selected');$('#drawTool').classList.remove('selected');
  const character=state.tokens.find(t=>t.id===session.characterId);
  $('#profileRole').textContent=master()?'Мастер игры':`Игрок · ${character.name}`;
  $('.avatar').textContent=master()?'М':character.name[0];
  const charNav=$('[data-view="characters"] span');charNav.textContent=master()?'Персонажи':'Мой персонаж';
  titles.characters=master()?['Ваш отряд','Герои, которым предстоит изменить эту историю.']:['Мой персонаж',`Ваша история начинается здесь, ${character.name}.`];
  document.querySelector('[data-view="table"]').click();render();
  try{localStorage.setItem(sessionKey,JSON.stringify(session))}catch{notify('Роль выбрана. Браузер не разрешил запомнить вход.')}
}
for(const card of document.querySelectorAll('[data-entry-role]'))card.onclick=()=>{
  selectedRole=card.dataset.entryRole;
  document.querySelectorAll('[data-entry-role]').forEach(b=>b.setAttribute('aria-pressed',String(b===card)));
  $('#entryCharacterField').hidden=selectedRole!=='player';
  const noHeroes=selectedRole==='player'&&!state.tokens.some(t=>t.kind==='hero');
  $('#entryContinue').disabled=noHeroes;
  $('#entryContinue').innerHTML=(selectedRole==='master'?'Войти как мастер':'Войти как игрок')+' <span>→</span>';
  $('#entryRoleHint').textContent=noHeroes?'В кампании пока нет героев. Мастер может добавить персонажа.':selectedRole==='master'?'Вы управляете кампанией, сценой и ходом приключения.':'Вы управляете своим героем и участвуете в общей истории.';
};
$('#entryForm').onsubmit=e=>{e.preventDefault();if(!selectedRole)return;enter({role:selectedRole,...(selectedRole==='player'?{characterId:$('#entryCharacter').value}:{})})};
$('#switchRole').onclick=()=>{try{localStorage.removeItem(sessionKey)}catch{}showEntry();$('#entryTitle').focus()};
$('#entryTheme').onclick=()=>$('#themeOpen').click();
showEntry();
try{const saved=JSON.parse(localStorage.getItem(sessionKey));if(validSession(saved,state.tokens))enter(saved)}catch{}
